import{_ as n,a0 as r,w as p,s as o,ao as d,I as l,x as s,a1 as e,A as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const f=JSON.parse('{"title":"开发者需要了解的领域特定语言（DSL） | LCTT x X-CMD","titleTemplate":false,"description":"开发者需要了解的领域特定语言（DSL） | LCTT (202003) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"开发者需要了解的领域特定语言（DSL） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"开发者需要了解的领域特定语言（DSL） | LCTT (202003) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202003/20200224 What developers need to know about domain-specific languages","title":"开发者需要了解的领域特定语言（DSL）","tag":"202003","desc":""},"relativePath":"202003/20200224 What developers need to know about domain-specific languages.md","filePath":"[post].md"}'),u={name:"202003/20200224 What developers need to know about domain-specific languages.md"};function L(S,a,D,b,h,g){const i=r("Link");return p(),o("div",null,[a[23]||(a[23]=d(`<h1 id="开发者需要了解的领域特定语言-dsl" tabindex="-1">开发者需要了解的领域特定语言（DSL） <a class="header-anchor" href="#开发者需要了解的领域特定语言-dsl" aria-label="Permalink to “开发者需要了解的领域特定语言（DSL）”">​</a></h1><blockquote><p>领域特定语言是在特定领域下用于特定上下文的语言。作为开发者，很有必要了解领域特定语言的含义，以及为什么要使用特定领域语言。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202003/04/112240b0os2988kolritlo.jpg" alt=""></p><p><ruby>领域特定语言<rt>domain-specific language</rt></ruby>（DSL）是一种旨在特定领域下的上下文的语言。这里的领域是指某种商业上的（例如银行业、保险业等）上下文，也可以指某种应用程序的（例如 Web 应用、数据库等）上下文。与之相比的另一个概念是<ruby>通用语言<rt>general-purpose language</rt></ruby>（GPL，LCTT 译注：注意不要和 GPL 许可证混淆），通用语言则可以广泛应用于各种商业或应用问题当中。</p><p>DSL 并不具备很强的普适性，它是仅为某个适用的领域而设计的，但它也足以用于表示这个领域中的问题以及构建对应的解决方案。HTML 是 DSL 的一个典型，它是在 Web 应用上使用的语言，尽管 HTML 无法进行数字运算，但也不影响它在这方面的广泛应用。</p><p>而 GPL 则没有特定针对的领域，这种语言的设计者不可能知道这种语言会在什么领域被使用，更不清楚用户打算解决的问题是什么，因此 GPL 会被设计成可用于解决任何一种问题、适合任何一种业务、满足任何一种需求。例如 Java 就属于 GPL，它可以在 PC 或移动设备上运行，嵌入到银行、金融、保险、制造业等各种行业的应用中去。</p><h3 id="dsl-的类别" tabindex="-1">DSL 的类别 <a class="header-anchor" href="#dsl-的类别" aria-label="Permalink to “DSL 的类别”">​</a></h3><p>从使用方式的角度，语言可以划分出以下两类：</p><ul><li>DSL：使用 DSL 形式编写或表示的语言</li><li><ruby>宿主语言<rt>host language</rt></ruby>：用于执行或处理 DSL 的语言</li></ul><p>由不同的语言编写并由另一种宿主语言处理的 DSL 被称为<ruby>外部<rt>external</rt></ruby> DSL。</p><p>以下就是可以在宿主语言中处理的 SQL 形式的 DSL：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>SELECT account</span></span>
<span class="line"><span>FROM accounts</span></span>
<span class="line"><span>WHERE account = &#39;123&#39; AND branch = &#39;abc&#39; AND amount &gt;= 1000</span></span></code></pre></div><p>因此，只要在规定了词汇和语法的情况下，DSL 也可以直接使用英语来编写，并使用诸如 ANTLR 这样的<ruby>解析器生成器<rt>parser generator</rt></ruby>以另一种宿主语言来处理 DSL：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>if smokes then increase premium by 10%</span></span></code></pre></div><p>如果 DSL 和宿主语言是同一种语言，这种 DSL 称为<ruby>内部<rt>internal</rt></ruby>DSL，其中 DSL 由以同一种语义的宿主语言编写和处理，因此又称为<ruby>嵌入式<rt>embedded</rt></ruby> DSL。以下是两个例子：</p><ul><li><p>Bash 形式的 DSL 可以由 Bash 解释器执行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span></span></span></code></pre></div></li></ul><p>if today_is_christmas; then apply_christmas_discount; fi</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    同时这也是一段看起来符合英语语法的 Bash。</span></span>
<span class="line"><span>* 使用类似 Java 语法编写的 DSL： </span></span>
<span class="line"><span></span></span>
<span class="line"><span>    \`\`\`</span></span>
<span class="line"><span>orderValue = orderValue</span></span>
<span class="line"><span>                .applyFestivalDiscount()</span></span>
<span class="line"><span>                .applyCustomerLoyalityDiscount()</span></span>
<span class="line"><span>                .applyCustomerAgeDiscount();</span></span></code></pre></div><pre><code>这一段的可读性也相当强。
</code></pre><p>实际上，DSL 和 GPL 之间并没有非常明确的界限。</p><h3 id="dsl-家族" tabindex="-1">DSL 家族 <a class="header-anchor" href="#dsl-家族" aria-label="Permalink to “DSL 家族”">​</a></h3><p>以下这些语言都可以作为 DSL 使用：</p><ul><li>Web 应用：HTML</li><li>Shell：用于类 Unix 系统的 sh、Bash、CSH 等；用于 Windows 系统的 MS-DOS、Windows Terminal、PowerShell 等</li><li>标记语言：XML</li><li>建模：UML</li><li>数据处理：SQL 及其变体</li><li>业务规则管理：Drools</li><li>硬件：Verilog、VHD</li><li>构建工具：Maven、Gradle</li><li>数值计算和模拟：MATLAB（商业）、GNU Octave、Scilab</li><li>解析器和生成器：Lex、YACC、GNU Bison、ANTLR</li></ul><h3 id="为什么要使用-dsl" tabindex="-1">为什么要使用 DSL？ <a class="header-anchor" href="#为什么要使用-dsl" aria-label="Permalink to “为什么要使用 DSL？”">​</a></h3><p>DSL 的目的是在某个领域中记录一些需求和行为，在某些方面（例如金融商品交易）中，DSL 的适用场景可能更加狭窄。业务团队和技术团队能通过 DSL 有效地协同工作，因此 DSL 除了在业务用途上有所发挥，还可以让设计人员和开发人员用于设计和开发应用程序。</p><p>DSL 还可以用于生成一些用于解决特定问题的代码，但生成代码并不是 DSL 的重点并不在此，而是对专业领域知识的结合。当然，代码生成在领域工程中是一个巨大的优势。</p><h3 id="dsl-的优点和缺点" tabindex="-1">DSL 的优点和缺点 <a class="header-anchor" href="#dsl-的优点和缺点" aria-label="Permalink to “DSL 的优点和缺点”">​</a></h3><p>DSL 的优点是，它对于领域的特征捕捉得非常好，同时它不像 GPL 那样包罗万有，学习和使用起来相对比较简单。因此，它在专业人员之间、专业人员和开发人员之间都提供了一个沟通的桥梁。</p><p>而 DSL 最显著的缺点就在于它只能用于一个特定的领域和目标。尽管学习起来不算太难，但学习成本仍然存在。如果使用到 DSL 相关的工具，即使对工作效率有所提升，但开发或配置这些工具也会增加一定的工作负担。另外，如果要设计一款 DSL，设计者必须具备专业领域知识和语言开发知识，而同时具备这两种知识的人却少之又少。</p><h3 id="dsl-相关软件" tabindex="-1">DSL 相关软件 <a class="header-anchor" href="#dsl-相关软件" aria-label="Permalink to “DSL  相关软件”">​</a></h3><p>开源的 DSL 软件包括：</p><ul><li>Xtext：Xtext 可以与 Eclipse 集成，并支持 DSL 开发。它能够实现代码生成，因此一些开源和商业产品都用它来提供特定的功能。用于农业活动建模分析的<ruby>多用途农业数据系统<rt>Multipurpose Agricultural Data System</rt></ruby>（MADS）就是基于 Xtext 实现的一个项目，可惜的是这个项目现在已经不太活跃了。</li><li>JetBrains MPS：JetBrains MPS 是一个可供开发 DSL 的<ruby>集成开发环境<rt>Integrated Development Environment</rt></ruby>，它将文档在底层存储为一个抽象树结构（Microsoft Word 也使用了这一概念），因此它也自称为一个<ruby>投影编辑器<rt>projectional editor</rt></ruby>。JetBrains MPS 支持 Java、C、JavaScript 和 XML 的代码生成。</li></ul><h3 id="dsl-的最佳实践" tabindex="-1">DSL 的最佳实践 <a class="header-anchor" href="#dsl-的最佳实践" aria-label="Permalink to “DSL 的最佳实践”">​</a></h3><p>如果你想使用 DSL，记住以下几点：</p>`,34)),l("ul",null,[a[3]||(a[3]=l("li",null,"DSL 不同于 GPL，DSL 只能用于解决特定领域中有限范围内的问题。",-1)),l("li",null,[a[1]||(a[1]=s("不必动辄建立自己的 DSL，可以首先尝试寻找已有的 DSL。例如 ",-1)),e(i,{href:"http://www.dslfin.org/resources.html"},{default:t(()=>[...a[0]||(a[0]=[s("DSLFIN",-1)])]),_:1}),a[2]||(a[2]=s(" 这个网站就提供了很多金融方面的 DSL。在实在找不到合适的 DSL 的情况下，才需要建立自己的 DSL。",-1))]),a[4]||(a[4]=l("li",null,"DSL 最好像平常的语言一样具有可读性。",-1)),a[5]||(a[5]=l("li",null,"尽管代码生成不是一项必需的工作，但它确实会大大提高工作效率。",-1)),a[6]||(a[6]=l("li",null,"虽然 DSL 被称为语言，但 DSL 不需要像 GPL 一样可以被执行，可执行性并不是 DSL 需要达到的目的。",-1)),a[7]||(a[7]=l("li",null,"DSL 可以使用文本编辑器编写，但专门的 DSL 编辑器可以更轻松地完成 DSL 的语法和语义检查。",-1))]),a[24]||(a[24]=l("p",null,"如果你正在使用或将要使用 DSL，欢迎在评论区留言。",-1)),a[25]||(a[25]=l("hr",null,null,-1)),l("p",null,[a[9]||(a[9]=s("via: ",-1)),e(i,{href:"https://opensource.com/article/20/2/domain-specific-languages"},{default:t(()=>[...a[8]||(a[8]=[s("https://opensource.com/article/20/2/domain-specific-languages",-1)])]),_:1})]),l("p",null,[a[14]||(a[14]=s("作者：",-1)),e(i,{href:"https://opensource.com/users/gammay"},{default:t(()=>[...a[10]||(a[10]=[s("Girish Managoli",-1)])]),_:1}),a[15]||(a[15]=s(" 选题：",-1)),e(i,{href:"https://github.com/lujun9972"},{default:t(()=>[...a[11]||(a[11]=[s("lujun9972",-1)])]),_:1}),a[16]||(a[16]=s(" 译者：",-1)),e(i,{href:"https://github.com/HankChow"},{default:t(()=>[...a[12]||(a[12]=[s("HankChow",-1)])]),_:1}),a[17]||(a[17]=s(" 校对：",-1)),e(i,{href:"https://github.com/wxy"},{default:t(()=>[...a[13]||(a[13]=[s("wxy",-1)])]),_:1})]),l("p",null,[a[20]||(a[20]=s("本文由 ",-1)),e(i,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...a[18]||(a[18]=[s("LCTT",-1)])]),_:1}),a[21]||(a[21]=s(" 原创编译，",-1)),e(i,{href:"https://linux.cn/"},{default:t(()=>[...a[19]||(a[19]=[s("Linux中国",-1)])]),_:1}),a[22]||(a[22]=s(" 荣誉推出",-1))])])}const y=n(u,[["render",L]]);export{f as __pageData,y as default};
